command:
timeout 110 bash -c 'node --input-type=module <<'\''NODE'\''
import fs from '\''node:fs/promises'\'';
process.env.CREW_DATA_DIR='\''data/w2-browser-proof'\'';
const { startServer, createContext, child }=await import(new URL('\''./scripts/acceptance-runtime.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const server=await startServer();
try {
 const ctx=createContext(server.url,{},[]); await ctx.api('\''POST'\'','\''/auth/login'\'',{email:'\''browser@work.test'\'',password:'\''browser-password-2026'\''});
 const project=(await ctx.api('\''GET'\'','\''/projects'\'')).items.find(project=>project.key==='\''BROW'\'');
 await fs.writeFile('\''/tmp/w2-browser-diagnostic.py'\'',Buffer.from('\'''\'','\''base64'\''));
 const report=await child('\''/usr/bin/python3'\'',['\''/tmp/w2-browser-diagnostic.py'\''],{env:{...process.env,CREW_BROWSER_URL:server.url,WORK_IDS:JSON.stringify({projectId:project.id})},deadline:30000}); console.log(report.stdout);
} finally {await server.stop();}
NODE
'

